{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "EM574, a macrolide with a dimethylamino sugar and neutral sugar, has an estimated human oral bioavailability of ~2% (oral CL/F ~4500 L/h vs hepatic blood flow), directly demonstrating that this macrolide class can have very low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "A complex glycosylated macrocycle (AVEs) showed low oral bioavailability relative to the assay LLOQ in participants, supporting poor absorption for large glycosylated macrolactones.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Glycyrrhizin, a large glycoside, has an absolute oral bioavailability of ~0.25% in humans, indicating that highly glycosylated natural products can be essentially non-absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "YH4808 has an absolute oral bioavailability of 10.1% (range 2.3-19.3%), below the 20% threshold, supporting low F for this compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Cefditoren has an absolute oral bioavailability of ~14% under fasting conditions in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Oseltamivir, a small ester prodrug, has an absolute oral bioavailability of 79±12% in healthy subjects, which is high; however, its small size and prodrug design limit transfer to the query's large macrolide.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "Etoposide, a glycosylated natural product, has oral bioavailability of 25-75% in patients, above the 20% threshold, providing some contradictory evidence that glycosylation does not preclude adequate F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction is low: the most transferable macrolide evidence (EM574) shows ~2% human oral bioavailability, and multiple large glycosides/macrolides show low F; high-F comparators are structurally distant or variable.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule",
    "No human F data for a 16-membered macrolide with the same substitution pattern",
    "Formulation/food effects and transporter/metabolism contributions not quantified"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

